\begin{lemma}\thlabel{lem:rel}
We have $L^\infty\subseteq \U \subseteq L^1$ and $L^\infty\subseteq \Y\subseteq L^1$ and 
\begin{align*}
\sigma(L^1,L^\infty)|_\U&\subseteq\sigma(\U,\Y),\quad\sigma(\U,\Y)|_{L^\infty}\subseteq\sigma(L^\infty,L^1),\\
\tau(L^1,L^\infty)|_\U&\subseteq\tau(\U,\Y),\quad\tau(\U,\Y)|_{L^\infty}\subseteq\tau(L^\infty,L^1).
\end{align*}
The $L^0$-topology on $\U$ is weaker than $\tau(\U,\Y)$.
\end{lemma}

\begin{theorem}\thlabel{thm:cif0}
If $h$ is a convex normal integrand with $\dom Eh\ne\emptyset$, then  
\[
(Eh)^*=Eh^*.
\]
Moreover, $y\in\partial Eh(u)$ if and only if $Eh(u)$ is finite and $y\in\partial h(u)$ almost surely.
\end{theorem}

\begin{proof}
The first claim follows by applying \cite[Theorem~14.60]{rw98} to the normal integrand $h_y(u,\omega):=h(u,\omega)-u\cdot y(\omega)$, where $y\in\Y$. As to the second, we have $y\in\partial Eh(u)$ if and only if $Eh(u)$ is finite and $Eh(u)+(Eh)^*(y)=\langle u,y\rangle$. Since $(Eh)^*=Eh^*$ by the first part,  the equality holds, by Fenchel's inequality, if and only if
\[
h(u)+h^*(y)=u\cdot y
\]
almost surely. This means that $y\in\partial h(u)$ almost surely.
\end{proof}

\begin{corollary}\thlabel{cor:cif}
Let $h$ be a convex normal integrand. The following are equivalent
\begin{enumerate}
\item $\dom Eh \ne\emptyset$ and  $\dom E h^* \ne\emptyset$,
\item $Eh$ is proper and closed,
%\item $Eh^*$ is proper and lsc,
\item $\dom Eh\ne\emptyset$ and there exists $y\in\Y$ and $\alpha\in L^1$ such that
\begin{align*}
h(u,\omega)\ge u\cdot y(\omega)-\alpha(\omega)
\end{align*}
\end{enumerate}
and imply that  $Eh$ and $E h^*$ are conjugates of each other and that $y\in\partial Eh(u)$ if and only if $y\in\partial h(u)$ almost surely.
\end{corollary}

\begin{proof}
By \thref{thm:cif0}, 1 implies 2. Assuming 2, there exists $u\in\dom Eh$, $y\in\Y$ and $a\in\reals$ such that
\[
Eh(u)\ge \langle u,y\rangle-a\quad\forall u\in\U
\]
Thus, by \thref{thm:cif0},
\[
a \ge (Eh)^*(y)=Eh^*(y).
\]
By Fenchel's inequality
\[
h(u,\omega)+h^*(y,\omega)\ge u\cdot y,
\]
so 3 holds with $\alpha(\omega)=h^*(y(\omega),\omega)$. If 3 holds, $Eh^*(y)\le E\alpha$, so 1 holds. By \thref{thm:cif0}, $Eh$ and $Eh^*$ are conjugates of each other and $y\in\partial Eh(u)$ implies $y\in\partial h(u)$ almost surely. If $y\in\partial h(u)$, then $h(u)+h^*(y)=u\cdot y$ almost surely, where each summand is integrable, since $Eh$ and $Eh^*$ are proper, so $Eh(u)+Eh^*(y)=\langle u,y\rangle$, which means that $y\in\partial Eh(u)$.
\end{proof}

\begin{lemma}\thlabel{lem:dual}
If $\dom Ef\cap(\X\times\U)\ne\emptyset$, then
\begin{align*}
F^*(v,p,y) &= Ef^*(v+p,y)+\delta_{\X_a^\perp}(p),
\end{align*}
and, in particular, 
\[
\varphi^*(p,y)= Ef^*(p,y)+\delta_{\X_a^\perp}(p).
\]
If, in addition, $\dom Ef^*\cap(\V\times\Y)\ne\emptyset$, then $F$ is proper and closed.
\end{lemma}

\begin{proof}
By the interchange rule \cite[Theorem~14.60]{rw98},
\begin{align*}
F^*(v,p,y) &= \sup_{x\in\X,z\in\X,u\in\U}\{\langle x,v\rangle + \langle z,p\rangle + \langle u,y\rangle - Ef(x,u) \,|\, x-z\in\X_a\}\\
&= \sup_{x\in \X,z'\in\X,u\in\U}\{E[x\cdot(v+p) + u\cdot y - f(x,u) - z'\cdot p] \,|\, z'\in\X_a\}\\
&= Ef^*(v+p,y)+\delta_{\X_a^\perp}(p).
\end{align*}
When $\dom Ef^*\ne\emptyset$, $Ef$ is proper and closed, by \thref{cor:cif}, so $F$ is closed as a sum of proper and closed functions. Clearly, $F$ is proper.
\end{proof}

As an immediate corollary, we get the following.


\begin{theorem}\thlabel{thm:dualproblem}
If $\dom Ef\cap(\X\times\U)\ne\emptyset$, the dual problem \eqref{d} can be written as
\begin{equation}\label{d}\tag{$D$}
\maximize\quad \langle\bar u,y\rangle - Ef^*(p,y)\quad\ovr\quad (p,y)\in\X_a^\perp\times\Y.
\end{equation}
\end{theorem}

\begin{lemma}\thlabel{lem:vperp}
The set $\X_a$ is $\sigma(\X,\V)$-closed and
%\[
%\X_a = \{x\in\X\mid \langle x,v\rangle = 0\quad\forall v\in\X_a^\perp\}.
%\]
%If $\X$ and $\V$ are solid [this has been already made a standing assumption??], then
\[
\X_a^\perp = \N^\perp\cap\V = \{v\in\V\,|\,E_tv_t=0\quad t=0,\ldots,T\}.
\]
\end{lemma}

\begin{proof}
Since $\N$ $\N$ is closed in $L^0$, Lemma~\ref{lem:rel} implies that $\X_a$ is closed in $\tau(\X,\V)$ and thus, by convexity, also in $\sigma(\X,\V)$. %The first equality thus follows from the bipolar theorem (see \thref{cor:bpt}).
Since
\[
\X_a = \X_0(\F_0)\times\cdots\times\X_T(\F_T),
\]
we have $v\in\X_a^\perp$ if and only if $E[x_t\cdot v_t]=0$ for every $x_t\in\X_t(\F_t)$. Here, $E[x_t\cdot v_t]=E[x_t\cdot (E_t v_t)]$, by \thref{lem:ce}.
\end{proof}

\begin{lemma}\thlabel{lem:perp}
Let $x\in\N$ and $v\in\N^\perp$. If $E[x\cdot v]^+\in L^1$, then $E[x\cdot v]=0$.
\end{lemma}

\begin{proof}
The assumptions imply that $f$ is proper so the equivalence of 2 and 3 follows from \cite[Theorem~37.5]{roc70a}. Let $x\in \N$ and $(p,y)\in \V\times\Y$ be feasible. By Fenchel's inequality,
\[
f(x,u)+f^*(p,y)-\bar u\cdot y \ge x\cdot p\quad P\text{-a.s.}
\]
so 
\[
Ef(x,u)+E[f^*(p,y)-\bar u\cdot y]\ge E[x\cdot p]
\]
and one holds as an equality if and only if the other one does. Equality in the former means that 2 holds. By Lemma~\ref{lem:perp}, $E[x\cdot p]=0$, so equality in the latter means that 1 holds.
\end{proof}

\begin{lemma}\thlabel{lem:Esum}
Given extended real-valued random variables $\xi_1$ and $\xi_2$, we have
\[
E[\xi_1+\xi_2]=E[\xi_1]+E[\xi_2]
\]
under any of the following:
\begin{enumerate}
\item\label{int1}
  $\xi_1^+,\xi_2^+\in L^1$ or $\xi_1^-,\xi_2^-\in L^1$.
  \item\label{int2}
  $\xi_1\in L^1$ or $\xi_2\in L^1$,
\item\label{int4}
  $\xi_1$ or $\xi_2$ is $\{0,+\infty\}$-valued.
\end{enumerate}
\end{lemma}

\begin{lemma}\thlabel{lem:ce}
Let $\xi_1$ and $\xi_2$ be extended real-valued random variables.
\begin{enumerate}
\item
  If $\xi_1$ and $\xi_2$ are quasi-integrable and satisfy any of the conditions in Lemma~\ref{lem:Esum}, then $\xi_1+\xi_2$ is quasi-integrable and
  \[
  E^\G[\xi_1+\xi_2] = E^\G [\xi_1] + E^\G[\xi_2].
  \]
\item
  If $\xi_2$ and $(\xi_1\xi_2)$ are quasi-integrable, and $\xi_1$ is $\G$-measurable, then
  \[
  E^\G[\xi_1\xi_2] = \xi_1E^\G[\xi_2].
  \]
\end{enumerate}
\end{lemma}

